def RecursiveBinarySearch(DataArray, Lower, Upper, DataToFind):   # header with four parameters
    if Upper >= Lower:                                             # range not empty (otherwise fall through to return -1)
        Middle = Lower + (Upper - Lower) // 2                      # middle index
        if DataArray[Middle] == DataToFind:                        # found: return the index
            return Middle
        elif DataArray[Middle] > DataToFind:                       # too high: search lower half (recursive, Middle - 1)
            return RecursiveBinarySearch(DataArray, Lower, Middle - 1, DataToFind)
        else:                                                      # too low: search upper half (recursive, Middle + 1)
            return RecursiveBinarySearch(DataArray, Middle + 1, Upper, DataToFind)
    else:
        return -1                                                  # not found

def RecursiveCount(DataToFind, ArrayCopy, NumberElements):
    if NumberElements > 0:                                                      # base case when no elements: return 0 below
        NewArray = ArrayCopy[1:]                                                # array without the first element
        if ArrayCopy[0] == DataToFind:                                          # compare first element with DataToFind
            return 1 + RecursiveCount(DataToFind, NewArray, NumberElements - 1) # match: 1 + recursive call
        else:
            return RecursiveCount(DataToFind, NewArray, NumberElements - 1)     # no match: recursive call only
    else:
        return 0                                                                # no elements: return 0
